
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbe_gaussian_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbe_gaussian", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.303462476007054e+00, -4.221748107636307e+00, -4.107356603496036e+00, -3.949126725161992e+00, -3.734003469559045e+00, -3.448709429266345e+00, -3.083622142787826e+00, -2.639596539225162e+00, -2.136176563472924e+00, -1.610336063235239e+00, -1.087326815579198e+00, -7.092143045933971e-01, -6.021124941914791e-01, -5.013186203181477e-01, -3.704442867351870e-01, -2.428187904261712e-01, -1.333540402197565e-01, -4.952124362326444e-02, -1.081192959976125e-02, -1.216202434215506e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


